describe('Password Authentication Error Handling', () => {
  beforeEach(() => {
    cy.visit('/login');
  });

  it('should display error message when user enters incorrect password', () => {
    // Intercept the login API call
    cy.intercept('POST', '/api/auth/login').as('loginAttempt');

    // Attempt to login with incorrect password
    cy.get('[data-testid="password-input"]').type('wrongPassword123');
    cy.get('[data-testid="submit-button"]').click();

    // Wait for the API response
    cy.wait('@loginAttempt').then((interception) => {
      expect(interception.response.statusCode).to.equal(401);
    });

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Invalid credentials');

    // Verify password input still contains the incorrect password
    cy.get('[data-testid="password-input"]').should('have.value', 'wrongPassword123');

    // Verify login button is still enabled
    cy.get('[data-testid="submit-button"]').should('be.enabled');
  });

  it('should clear error message when user enters correct password', () => {
    // Intercept the login API call
    cy.intercept('POST', '/api/auth/login').as('loginAttempt');

    // Attempt to login with incorrect password
    cy.get('[data-testid="password-input"]').type('wrongPassword123');
    cy.get('[data-testid="submit-button"]').click();

    // Wait for the API response
    cy.wait('@loginAttempt').then((interception) => {
      expect(interception.response.statusCode).to.equal(401);
    });

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Invalid credentials');

    // Clear error message
    cy.get('[data-testid="error-message"]').should('not.exist');

    // Reset password input
    cy.get('[data-testid="password-input"]').clear();

    // Attempt to login with correct password
    cy.get('[data-testid="password-input"]').type('correctPassword123');
    cy.get('[data-testid="submit-button"]').click();

    // Wait for the API response
    cy.wait('@loginAttempt').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
    });

    // Verify success message is displayed
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Login successful');

    // Verify error message is no longer present
    cy.get('[data-testid="error-message"]').should('not.exist');
  });
});
